#include <iostream>
using namespace std;

using i128 = __int128_t;

const i128 cost[10] = {6, 2, 5, 5, 4, 5, 6, 3, 7, 6};

i128 prefixCost(i128 n) {
    if (n < 0) return 0;

    i128 total = cost[0]; // Number 0

    for (i128 factor = 1; factor <= n; factor *= 10) {
        i128 lower = n % factor;
        i128 current = (n / factor) % 10;
        i128 higher = n / (factor * 10);

        if (higher > 0) {
            i128 countZero = (higher - 1) * factor;
            countZero += (current == 0 ? lower + 1 : factor);
            total += countZero * cost[0];
        }

        for (int digit = 1; digit <= 9; ++digit) {
            i128 count = higher * factor;
            if (current > digit)
                count += factor;
            else if (current == digit)
                count += lower + 1;

            total += count * cost[digit];
        }

        if (factor > n / 10) break;
    }

    return total;
}

void printInt128(i128 value) {
    if (value == 0) {
        cout << '0';
        return;
    }

    if (value < 0) {
        cout << '-';
        value = -value;
    }

    string result;
    while (value > 0) {
        result += char('0' + value % 10);
        value /= 10;
    }

    for (auto it = result.rbegin(); it != result.rend(); ++it)
        cout << *it;
}

int main() {
    long long a, b;
    cin >> a >> b;

    i128 answer = prefixCost((i128)b) - prefixCost((i128)a - 1);
    printInt128(answer);

    return 0;
}

#include <iostream>
using namespace std;

using int128 = __int128_t;

const int matchsticks[10] = {6, 2, 5, 5, 4, 5, 6, 3, 7, 6};

int128 prefixSum(long long n) {
    if (n < 0) return 0;

    int128 limit = n;
    int128 total = matchsticks[0];

    for (int128 factor = 1; factor <= limit; factor *= 10) {
        int128 higher = limit / (factor * 10);
        int digit = static_cast<int>((limit / factor) % 10);
        int128 lower = limit % factor;

        for (int d = 1; d <= 9; ++d) {
            int128 count = higher * factor;
            if (digit > d)
                count += factor;
            else if (digit == d)
                count += lower + 1;

            total += count * matchsticks[d];
        }

        if (higher > 0) {
            int128 count = (higher - 1) * factor;
            count += (digit == 0) ? lower + 1 : factor;
            total += count * matchsticks[0];
        }
    }

    return total;
}

void printInt128(int128 value) {
    if (value == 0) {
        cout << '0';
        return;
    }

    if (value < 0) {
        cout << '-';
        value = -value;
    }

    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }

    for (auto it = result.rbegin(); it != result.rend(); ++it)
        cout << *it;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b;
    cin >> a >> b;

    if (a > b) {
        cout << 0;
        return 0;
    }

    printInt128(prefixSum(b) - prefixSum(a - 1));
    return 0;
}

