#include <iostream>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

const int matchsticks[10] = {6, 2, 5, 5, 4, 5, 6, 3, 7, 6};

i128 prefixSum(int64 n) {
    if (n < 0) return 0;

    i128 result = matchsticks[0]; // Number 0

    for (int64 factor = 1; factor <= n; ) {
        int64 high = n / factor / 10;
        int64 current = (n / factor) % 10;
        int64 low = n % factor;

        for (int digit = 1; digit <= 9; ++digit) {
            i128 count = static_cast<i128>(high) * factor;

            if (current > digit)
                count += factor;
            else if (current == digit)
                count += low + 1;

            result += count * matchsticks[digit];
        }

        if (high > 0) {
            i128 zeroCount = static_cast<i128>(high - 1) * factor;
            zeroCount += (current == 0) ? low + 1 : factor;
            result += zeroCount * matchsticks[0];
        }

        if (factor > n / 10) break;
        factor *= 10;
    }

    return result;
}

void printInt128(i128 value) {
    if (value == 0) {
        cout << '0';
        return;
    }

    if (value < 0) {
        cout << '-';
        value = -value;
    }

    string output;
    while (value > 0) {
        output.push_back('0' + value % 10);
        value /= 10;
    }

    for (auto it = output.rbegin(); it != output.rend(); ++it)
        cout << *it;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b;
    cin >> a >> b;

    if (a > b) {
        cout << 0;
        return 0;
    }

    i128 answer = prefixSum(b) - (a > 0 ? prefixSum(a - 1) : 0);
    printInt128(answer);

    return 0;
}

